UPDATE copa_produto
SET desc_en = 'Germany entered as four-time world champions with one of football''s most intimidating knockout reputations. Paraguay entered as the underdog. After 120 dramatic minutes and a historic penalty shootout, everything had changed. How Paraguay Broke Germany is a premium 26-page digital match file that reveals why Paraguay''s victory was far more than luck.',
    desc_pt_pt = 'A Alemanha entrava em campo como tetracampeã mundial, com uma das reputações mais intimidantes do futebol em fases eliminatórias. O Paraguai entrava como azarão. Depois de 120 minutos dramáticos e um histórico desempate por grandes penalidades, tudo tinha mudado. How Paraguay Broke Germany é um ficheiro digital premium de 26 páginas sobre esse jogo, que revela porque é que a vitória do Paraguai foi muito mais do que sorte.',
    desc_pt_br = 'A Alemanha entrava em campo como tetracampeã mundial, com uma das reputações mais intimidadoras do futebol em jogos eliminatórios. O Paraguai entrava como azarão. Depois de 120 minutos dramáticos e uma histórica disputa de pênaltis, tudo tinha mudado. How Paraguay Broke Germany é um arquivo digital premium de 26 páginas sobre essa partida, que revela por que a vitória do Paraguai foi muito mais do que sorte.'
